import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime='/home/runner/.local/share/omgithub-playwright';
const require=createRequire(runtime+'/package.json');
const { chromium }=require('playwright');
const config=JSON.parse(readFileSync(runtime+'/linux.json','utf8'));
const browser=await chromium.launch({...config.browser.launchOptions});
const page=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});
page.on('pageerror',e=>console.log('ERR',e.message));
await page.goto('http://localhost:3002',{waitUntil:'networkidle'});
await page.locator('#start').click();
const box=await page.locator('#joystick').boundingBox();
const x=box.x+box.width/2,y=box.y+box.height/2;
console.log('at start',await page.evaluate(()=>window.__gameDebug()));
await page.mouse.move(x,y); await page.mouse.down();
await page.mouse.move(x-22,y+23,{steps:8});
console.log('input',await page.evaluate(()=>window.__gameDebug()));
await page.waitForTimeout(1000);
console.log('1 sec',await page.evaluate(()=>window.__gameDebug()));
await page.waitForTimeout(3700);
console.log('4.7 sec',await page.evaluate(()=>window.__gameDebug()));
await page.mouse.up();
await page.screenshot({path:'/tmp/opencode/debug-move.png'});
console.log('hint',await page.locator('#hint').textContent());
await browser.close();

