--- index.html
+++ index.html
@@ -76,9 +76,9 @@
  {name:'Omar',role:'atiende el centro cívico',x:27,z:4,color:'#668a75',title:'Una indicación amable',desc:'Omar te pregunta si sabes dónde está la biblioteca municipal.',answers:['Está al norte, junto a la avenida.','Está en Marte, a la izquierda.','No hablo con terrícolas.'],correct:0},
