 ];
 const jobs={cafe:{title:'Un pedido en Café Estrella',desc:'La clienta pide algo sencillo para empezar el día. ¿Qué le sirves?',answers:['Un café con leche, por favor.','Una taza de agua de mar.','Tres pilas y una pajita.'],correct:0},mail:{title:'Paquetes para clasificar',desc:'La dirección dice: Calle Luna 12. ¿En qué estante va?',answers:['Calle Sol 12.','Calle Luna 12.','Luna, el satélite.'],correct:1},hall:{title:'Recepción del centro cívico',desc:'Un vecino pregunta dónde renovar su tarjeta.',answers:['Buenos días, ventanilla dos.','Vengo de otro planeta.','Beep boop.'],correct:0}};
-function makePeople(){for(const actor of [player,...crew,...civilians,...ambientPeople,...traffic.map(car=>car.root)])if(actor)scene.remove(actor);player=makeActor('Luma',colors[0],true);player.position.set(-3,0,3);scene.add(player);crew=[];for(let i=1;i<4;i++){const a=makeActor(names[i],colors[i],true);a.position.set(-3-i*1.6,0,5+i);scene.add(a);crew.push(a)}civilians=chats.map((c,i)=>{const a=makeActor(c.name,c.color,false);a.position.set(c.x,0,c.z);a.userData.chat=c;a.userData.phase=i*1.7;scene.add(a);makeActivity(a,c.name);return a});spawnAmbientPeople();spawnTraffic();camera.position.set(-2.4,camera.fov>45?5.8:4.2,camera.fov>45?13.5:8);camera.lookAt(-3,1.15,3);
+function makePeople(){for(const actor of [player,...crew,...civilians,...ambientPeople,...traffic.map(car=>car.root)])if(actor)scene.remove(actor);player=makeActor('Luma',colors[0],true);player.position.set(-5,0,4.5);scene.add(player);crew=[];for(let i=1;i<4;i++){const a=makeActor(names[i],colors[i],true);a.position.set(-5-i*1.6,0,4.5+i*2);scene.add(a);crew.push(a)}civilians=chats.map((c,i)=>{const a=makeActor(c.name,c.color,false);a.position.set(c.x,0,c.z);a.userData.chat=c;a.userData.phase=i*1.7;scene.add(a);makeActivity(a,c.name);return a});spawnAmbientPeople();spawnTraffic();camera.position.set(-4.75,camera.fov>45?5.8:3.35,camera.fov>45?15:8.85);camera.lookAt(-5,1.12,4.5);
  document.querySelector('#crew').innerHTML=names.map((n,i)=>`<div class="crew-row"><div class="avatar" style="background:${colors[i]}30;color:${colors[i]}">✦</div><div><div class="crew-name">${n}</div><div class="crew-role">${i===0?'Tú':'Alien aliado'}</div></div></div>`).join('')}
 function spawnAmbientPeople(){const routes=[[[-20,-4.55],[20,-4.55],[20,4.55],[-20,4.55]],[[-20,4.55],[20,4.55],[20,-4.55],[-20,-4.55]],[[-4.55,-20],[-4.55,20],[4.55,20],[4.55,-20]],[[4.55,-20],[4.55,20],[-4.55,20],[-4.55,-20]],[[ -20,-4.55],[-4.55,-4.55],[-4.55,-20],[4.55,-20],[4.55,-4.55],[20,-4.55]],[[20,4.55],[4.55,4.55],[4.55,20],[-4.55,20],[-4.55,4.55],[-20,4.55]]];const people=[['Clara','#bd7861'],['Mateo','#6689a4'],['Sofi','#b58b5e'],['Dani','#8d789e'],['Pablo','#668a75'],['Nora','#bd7180']];ambientPeople=people.map(([name,color],i)=>{const a=makeActor(name,color,false),route=routes[i];a.children[a.children.length-1].visible=false;a.position.set(route[0][0],0,route[0][1]);a.userData.route=route;a.userData.waypoint=1;a.userData.phase=i*1.9;scene.add(a);return a})}
  function makeCar(axis,road,direction,coordinate,color){const lane=road+(direction>0?-1.8:1.8),root=new THREE.Group(),paint=mat(color),glass=mat('#a9c5c6'),tire=mat('#24292d'),rim=mat('#9ca4a0'),lamp=mat('#f6df9e'),tail=mat('#d95046');box(root,0,.46,0,1.58,.48,2.9,paint);box(root,0,.79,-.08,1.3,.36,1.55,glass);box(root,0,1.01,.92,1.5,.1,.2,paint);for(const side of [-1,1]){box(root,side*.79,.42,1.31,.07,.17,.22,lamp);box(root,side*.79,.42,-1.31,.07,.17,.22,tail);for(const end of [-1,1]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.27,.27,.15,10),tire);wheel.rotation.z=Math.PI/2;wheel.position.set(side*.78,.29,end*.9);root.add(wheel);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.12,.12,.16,8),rim);hub.rotation.z=Math.PI/2;hub.position.copy(wheel.position);root.add(hub)}}root.position.set(axis==='x'?coordinate:lane,.04,axis==='x'?lane:coordinate);scene.add(root);const car={root,axis,direction,coordinate,lane,road,speed:3.2+(Math.abs(road)%2)*.3,stopped:false,alarmed:false};root.rotation.y=axis==='x'?(direction>0?Math.PI/2:-Math.PI/2):(direction>0?0:Math.PI);return car}
  function spawnTraffic(){const specs=[['x',0,1,-35,'#d6755d'],['x',0,-1,35,'#5d8195'],['z',0,1,-10,'#d2ad54'],['z',0,-1,35,'#638c72'],['x',-25,1,-40,'#9678a8'],['z',25,-1,40,'#6d9c9b']];traffic=specs.map(spec=>makeCar(...spec))}

